var pipe = new Pipe();
Task writing = FillAsync(socket, pipe.Writer), filtering = FilterAsync(pipe.Reader, next.Writer);
await Task.WhenAll(writing, filtering);                   // pipeline driver
async Task FilterAsync(PipeReader reader, PipeWriter writer) {
    while (true) {
        ReadResult r = await reader.ReadAsync();
        foreach (var line in SplitLines(r.Buffer)) writer.Write(Transform(line));
        reader.AdvanceTo(r.Buffer.End);   // releases the consumed buffers
        if (r.IsCompleted) break;
    }
    await writer.CompleteAsync();         // EOF for the next stage
}

